fn_build_counts_plot &lt;- function(
  df,
  determinant_name,
  plot_subtitle
) {
  plot_data &lt;- df |&gt;
    filter(
      lsm &gt; 0
    ) |&gt;
    transmute(
      period_abbr,
      area,
      value = .data[[determinant_name]]
    ) |&gt;
    group_by(
      period_abbr,
      value
    ) |&gt;
    summarise(
      total_area = sum(
        area,
        na.rm = TRUE
      ),
      .groups = "drop"
    ) |&gt;
    group_by(
      period_abbr
    ) |&gt;
    mutate(
      prop_area = total_area /
        sum(total_area)
    ) |&gt;
    ungroup() |&gt;
    mutate(
      period_abbr = factor(
        period_abbr,
        levels = climate_periods$period_abbr
      )
    )

  ggplot(
    plot_data,
    aes(
      x = value,
      y = prop_area,
      fill = period_abbr
    )
  ) +
    geom_col(
      position = "dodge",
      width = 0.7
    ) +
    scale_y_continuous(
      labels = scales::percent_format(
        accuracy = 1
      )
    ) +
    scale_fill_manual(
      values = period_palette,
      breaks = climate_periods$period_abbr,
      labels = period_plot_labels,
      guide = guide_legend(
        nrow = 1,
        byrow = TRUE
      )
    ) +
    labs(
      subtitle = plot_subtitle,
      x = determinant_name,
      y = "Land Area %",
      fill = NULL
    ) +
    theme_minimal(base_size = 13) +
    theme(
      legend.position = "bottom",
      panel.grid.major.x = element_blank(),
      axis.title.x = element_text(size = 11.5)
    )
}

