fn_assign_ktc &lt;- function(df) {
  df |&gt;
    mutate(
      grp = case_when(
        TMAX &lt; 10 ~ "F",
        PTOT &lt; (ATHR * 10) ~ "B",
        TMIN &gt;= 18 ~ "A",
        TG10 &gt;= 8 ~ "C",
        TG10 &gt;= 4 ~ "D",
        TG10 &gt;= 1 ~ "E",
        TRUE ~ "X"
      ),
      typ = case_when(
        grp == "A" & PL60 &lt;= 2 ~ "r",
        grp == "A" ~ "w",
        grp == "B" & PTOT &lt; (ATHR * 10) / 2 ~ "W",
        grp == "B" ~ "S",
        grp == "C" &
          PWNT &gt;= PSMR * 3 &
          PMIN &lt; 30 &
          PTOT &lt; 890 ~ "s",
        grp == "C" &
          PSMR &gt;= PWNT * 10 ~ "w",
        grp == "C" ~ "f",
        grp == "D" &
          TMIN &gt; 0 ~ "o",
        grp == "D" ~ "c",
        grp == "E" &
          TMIN &gt; -10 ~ "o",
        grp == "E" ~ "c",
        grp == "F" &
          TMAX &gt; 0 ~ "t",
        grp == "F" ~ "i",
        TRUE ~ ""
      ),
      ktc = paste0(grp, typ),
      grp = factor(
        grp,
        levels = group_levels
      ),
      ktc = factor(
        ktc,
        levels = ktc_levels
      )
    ) |&gt;
    select(
      period_id,
      period_name,
      period_label,
      period_abbr,
      start_year,
      end_year,
      lon,
      lat,
      area,
      lsm,
      grp,
      ktc
    )
}

fn_class_summary &lt;- function(
  classification_df,
  class_variable,
  class_levels
) {
  classification_df |&gt;
    filter(lsm &gt; 0) |&gt;
    transmute(
      period_id,
      period_name,
      period_label,
      period_abbr,
      class = as.character(
        .data[[class_variable]]
      ),
      land_area = area * lsm
    ) |&gt;
    filter(
      !is.na(class),
      is.finite(land_area),
      land_area &gt; 0
    ) |&gt;
    group_by(
      period_id,
      period_name,
      period_label,
      period_abbr,
      class
    ) |&gt;
    summarise(
      mkm = sum(
        land_area,
        na.rm = TRUE
      ),
      .groups = "drop"
    ) |&gt;
    group_by(
      period_id,
      period_name,
      period_label,
      period_abbr
    ) |&gt;
    mutate(
      pct = mkm / sum(mkm)
    ) |&gt;
    ungroup() |&gt;
    complete(
      nesting(
        period_id,
        period_name,
        period_label,
        period_abbr
      ),
      class = class_levels,
      fill = list(
        mkm = 0,
        pct = 0
      )
    ) |&gt;
    mutate(
      class = factor(
        class,
        levels = class_levels
      ),
      period_abbr = factor(
        period_abbr,
        levels = climate_periods$period_abbr
      )
    ) |&gt;
    arrange(
      class,
      period_abbr
    )
}

fn_build_summary_gt &lt;- function(
  summary_df,
  title,
  stub_header
) {
  display_df &lt;- summary_df |&gt;
    mutate(
      period_abbr = as.character(period_abbr),
      class = as.character(class)
    ) |&gt;
    select(
      class,
      period_abbr,
      mkm,
      pct
    ) |&gt;
    pivot_wider(
      names_from = period_abbr,
      values_from = c(mkm, pct),
      names_glue = "{.value}_{period_abbr}"
    )

  mkm_cols &lt;- paste0(
    "mkm_",
    climate_periods$period_abbr
  )

  pct_cols &lt;- paste0(
    "pct_",
    climate_periods$period_abbr
  )

  display_df |&gt;
    select(
      class,
      all_of(mkm_cols),
      all_of(pct_cols)
    ) |&gt;
    gt(
      rowname_col = "class"
    ) |&gt;
    tab_header(
      title = title
    ) |&gt;
    tab_stubhead(
      label = stub_header
    ) |&gt;
    tab_spanner(
      label = "Area (Mkm²)",
      columns = all_of(mkm_cols)
    ) |&gt;
    tab_spanner(
      label = "Earth's Land Surface",
      columns = all_of(pct_cols)
    ) |&gt;
    cols_label(
      !!!setNames(
        as.list(climate_periods$period_abbr),
        mkm_cols
      ),
      !!!setNames(
        as.list(climate_periods$period_abbr),
        pct_cols
      )
    ) |&gt;
    cols_align(
      align = "right",
      columns = c(
        all_of(mkm_cols),
        all_of(pct_cols)
      )
    ) |&gt;
    fmt_number(
      columns = all_of(mkm_cols),
      decimals = 1
    ) |&gt;
    fmt_percent(
      columns = all_of(pct_cols),
      decimals = 1
    )
}

