}

fn_build_global_map &lt;- function(
  classification_df,
  period_id
) {
  period_row &lt;- climate_periods |&gt;
    filter(
      .data$period_id ==
        .env$period_id
    )

  if (nrow(period_row) != 1) {
    stop(
      "Expected exactly one climate period for ",
      period_id,
      "."
    )
  }

  map_df &lt;- classification_df |&gt;
    filter(
      .data$period_id ==
        .env$period_id,
      lsm &gt; 0
    ) |&gt;
    select(
      lon,
      lat,
      ktc
    )

  sf_plot &lt;- st_as_sf(
    map_df,
    coords = c(
      "lon",
      "lat"
    ),
    crs = 4326
  )

  ggplot() +
    geom_sf(
      data = sf_plot,
      aes(
        color = ktc
      ),
      size = 0.01
    ) +
    geom_sf(
      data = sf_coastline,
      inherit.aes = FALSE,
      color = "black",
      linewidth = 0.1
    ) +
    scale_color_manual(
      values = ktc_palette,
      drop = FALSE
    ) +
    coord_sf(
      crs = rbn_prj,
      datum = NA
    ) +
    labs(
      title = "Köppen–Trewartha Climate Classification",
      subtitle = paste0(
        period_row$period_label,
        " (",
        period_row$start_year,
        "–",
        period_row$end_year,
        ")"
      ),
      color = "Climate"
    ) +
    guides(
      color = guide_legend(
        override.aes = list(
          size = 5
        )
      )
    ) +
    theme_void() +
    theme(
      plot.title = element_text(
        face = "bold"
      )
    )
}

