# creates the three grid-cell transition datasets
fn_build_transition &lt;- function(
  classification_df,
  comparison_row
) {
  from_id &lt;- comparison_row$from_period_id[[1]]
  to_id &lt;- comparison_row$to_period_id[[1]]

  from_df &lt;- classification_df |&gt;
    filter(period_id == from_id) |&gt;
    transmute(
      lon,
      lat,
      area,
      lsm,
      from_grp = as.character(grp),
      from_ktc = as.character(ktc)
    )

  to_df &lt;- classification_df |&gt;
    filter(period_id == to_id) |&gt;
    transmute(
      lon,
      lat,
      to_area = area,
      to_lsm = lsm,
      to_grp = as.character(grp),
      to_ktc = as.character(ktc)
    )

  transition_df &lt;- from_df |&gt;
    inner_join(
      to_df,
      by = c("lon", "lat")
    )

  if (
    any(
      abs(transition_df$area - transition_df$to_area) &gt; 1e-8,
      na.rm = TRUE
    ) ||
      any(
        abs(transition_df$lsm - transition_df$to_lsm) &gt; 1e-8,
        na.rm = TRUE
      )
  ) {
    stop(
      "Grid-cell area or land-sea mask differs between ",
      comparison_row$comparison_label[[1]],
      " classification datasets."
    )
  }

  transition_df |&gt;
    transmute(
      comparison_id = comparison_row$comparison_id[[1]],
      comparison_label = comparison_row$comparison_label[[1]],
      from_period_id = from_id,
      to_period_id = to_id,
      lon,
      lat,
      area,
      lsm,
      land_area = area * lsm,
      from_grp,
      to_grp,
      from_ktc,
      to_ktc,
      group_changed = from_grp != to_grp,
      type_changed = from_ktc != to_ktc
    ) |&gt;
    filter(
      lsm &gt; 0,
      is.finite(land_area),
      land_area &gt; 0,
      !is.na(from_grp),
      !is.na(to_grp),
      !is.na(from_ktc),
      !is.na(to_ktc)
    )
}

# overall classification change summary
fn_change_overview &lt;- function(transitions_df) {
  transitions_df |&gt;
    group_by(
      comparison_id,
      comparison_label
    ) |&gt;
    summarise(
      total_land_area = sum(land_area, na.rm = TRUE),
      group_changed_area = sum(
        land_area[group_changed],
        na.rm = TRUE
      ),
      type_changed_area = sum(
        land_area[type_changed],
        na.rm = TRUE
      ),
      .groups = "drop"
    ) |&gt;
    mutate(
      group_changed_pct = group_changed_area / total_land_area,
      type_changed_pct = type_changed_area / total_land_area,
      comparison_label = factor(
        comparison_label,
        levels = comparison_levels
      )
    ) |&gt;
    arrange(comparison_label)
}

# group/type transition summaries
fn_transition_summary &lt;- function(
  transitions_df,
  from_variable,
  to_variable
) {
  transitions_df |&gt;
    transmute(
      comparison_id,
      comparison_label,
      from_class = .data[[from_variable]],
      to_class = .data[[to_variable]],
      land_area
    ) |&gt;
    group_by(
      comparison_id,
      comparison_label,
      from_class,
      to_class
    ) |&gt;
    summarise(
      mkm = sum(land_area, na.rm = TRUE),
      .groups = "drop"
    ) |&gt;
    group_by(
      comparison_id,
      comparison_label
    ) |&gt;
    mutate(
      pct = mkm / sum(mkm)
    ) |&gt;
    ungroup() |&gt;
    mutate(
      changed = from_class != to_class,
      comparison_label = factor(
        comparison_label,
        levels = comparison_levels
      )
    ) |&gt;
    arrange(
      comparison_label,
      desc(mkm)
    )
}

# group/type gains, losses, and net change
fn_net_change &lt;- function(
  transition_summary,
  class_levels
) {
  from_summary &lt;- transition_summary |&gt;
    group_by(
      comparison_id,
      comparison_label,
      class = from_class
    ) |&gt;
    summarise(
      from_mkm = sum(mkm),
      .groups = "drop"
    )

  to_summary &lt;- transition_summary |&gt;
    group_by(
      comparison_id,
      comparison_label,
      class = to_class
    ) |&gt;
    summarise(
      to_mkm = sum(mkm),
      .groups = "drop"
    )

  gains &lt;- transition_summary |&gt;
    filter(changed) |&gt;
    group_by(
      comparison_id,
      comparison_label,
      class = to_class
    ) |&gt;
    summarise(
      gain_mkm = sum(mkm),
      .groups = "drop"
    )

  losses &lt;- transition_summary |&gt;
    filter(changed) |&gt;
    group_by(
      comparison_id,
      comparison_label,
      class = from_class
    ) |&gt;
    summarise(
      loss_mkm = sum(mkm),
      .groups = "drop"
    )

  full_join(
    from_summary,
    to_summary,
    by = c(
      "comparison_id",
      "comparison_label",
      "class"
    )
  ) |&gt;
    full_join(
      gains,
      by = c(
        "comparison_id",
        "comparison_label",
        "class"
      )
    ) |&gt;
    full_join(
      losses,
      by = c(
        "comparison_id",
        "comparison_label",
        "class"
      )
    ) |&gt;
    complete(
      nesting(
        comparison_id,
        comparison_label
      ),
      class = class_levels
    ) |&gt;
    mutate(
      across(
        c(
          from_mkm,
          to_mkm,
          gain_mkm,
          loss_mkm
        ),
        ~ replace_na(.x, 0)
      ),
      total_land_area = sum(from_mkm, na.rm = TRUE),
      from_pct = from_mkm / total_land_area,
      to_pct = to_mkm / total_land_area,
      gain_pct = gain_mkm / total_land_area,
      loss_pct = loss_mkm / total_land_area,
      net_pct = (to_mkm - from_mkm) / total_land_area,
      comparison_label = factor(
        comparison_label,
        levels = comparison_levels
      ),
      class = factor(
        class,
        levels = class_levels
      ),
      .by = c(
        comparison_id,
        comparison_label
      )
    ) |&gt;
    arrange(
      comparison_label,
      class
    )
}

# build a transition matrices
fn_build_transition_matrix_gt &lt;- function(
  transition_summary,
  comparison,
  class_levels,
  title,
  hide_diagonal = TRUE
) {
  matrix_df &lt;- transition_summary |&gt;
    filter(
      comparison_label ==
        comparison
    ) |&gt;
    select(
      from_class,
      to_class,
      pct
    ) |&gt;
    complete(
      from_class = class_levels,
      to_class = class_levels,
      fill = list(
        pct = 0
      )
    ) |&gt;
    mutate(
      from_class = factor(
        from_class,
        levels = class_levels
      ),
      to_class = factor(
        to_class,
        levels = class_levels
      ),
      pct = if_else(
        hide_diagonal &
          as.character(from_class) ==
            as.character(to_class),
        NA_real_,
        pct
      )
    ) |&gt;
    arrange(
      from_class,
      to_class
    ) |&gt;
    pivot_wider(
      names_from = to_class,
      values_from = pct
    )

  matrix_df |&gt;
    gt(
      rowname_col = "from_class"
    ) |&gt;
    tab_header(
      title = title,
      subtitle = paste(
        comparison,
        "— percent of global land area"
      )
    ) |&gt;
    tab_stubhead(
      label = "From"
    ) |&gt;
    tab_spanner(
      label = "To",
      columns = all_of(
        class_levels
      )
    ) |&gt;
    fmt_percent(
      columns = all_of(
        class_levels
      ),
      decimals = 2
    ) |&gt;
    sub_missing(
      columns = all_of(
        class_levels
      ),
      missing_text = "—"
    )
}

# Largest Climate Type Transitions
fn_largest_transitions_gt &lt;- function(
  transition_summary,
  title,
  n = 12
) {
  transition_summary |&gt;
    filter(changed) |&gt;
    group_by(
      comparison_id,
      comparison_label
    ) |&gt;
    slice_max(
      order_by = mkm,
      n = n,
      with_ties = FALSE
    ) |&gt;
    ungroup() |&gt;
    mutate(
      transition = paste(
        from_class,
        "→",
        to_class
      )
    ) |&gt;
    select(
      comparison_label,
      transition,
      mkm,
      pct
    ) |&gt;
    arrange(
      comparison_label,
      desc(mkm)
    ) |&gt;
    gt(groupname_col = "comparison_label") |&gt;
    tab_header(
      title = title,
      subtitle = "Largest changed classifications by land area"
    ) |&gt;
    cols_label(
      transition = "Transition",
      mkm = "Area (Mkm²)",
      pct = "Land Area %"
    ) |&gt;
    fmt_number(
      columns = mkm,
      decimals = 2
    ) |&gt;
    fmt_percent(
      columns = pct,
      decimals = 2
    )
}

