fn_comparison_subtitle &lt;- function(comparison_id) {
  comparison_row &lt;- transition_comparisons |&gt;
    filter(
      .data$comparison_id ==
        .env$comparison_id
    )

  if (nrow(comparison_row) != 1) {
    stop(
      "Expected exactly one transition comparison for ",
      comparison_id,
      "."
    )
  }

  comparison_row$comparison_label[[1]]
}

